/**
 * papexBannerPick — which of the six PapeX banners a colourless store gets
 * (Nico, 2026-09-18). Pure, no React, no Expo, so `node --test` can load it
 * (services/__tests__/papexBannerPick.test.mjs).
 *
 * A store with no colours of its own (no `brandColor`, and no colours read off
 * a logo) is drawn in one of `PAPEX_BANNER_COUNT` PapeX-branded banners (see
 * `storeBanners.tsx`). The pick is a stable hash of the store id, so different
 * stores look different but a given store gets the same banner on every screen
 * and every launch.
 */

/** How many PapeX banner designs exist. `storeBanners.tsx` draws exactly this many. */
export const PAPEX_BANNER_COUNT = 6;

/**
 * FNV-1a 32-bit over the id's UTF-16 code units. Chosen over `id.length` or a
 * char-sum because ids like `auto-safeway` / `auto-safeways` differ by one
 * character, and FNV-1a's multiply spreads a one-character change across
 * every bit.
 */
export function stableIdHash(id: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < id.length; i += 1) {
    hash ^= id.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

/** The banner variant, 0 .. PAPEX_BANNER_COUNT - 1, for a store id. */
export function papexBannerIndex(storeId: string): number {
  return stableIdHash(typeof storeId === 'string' ? storeId : '') % PAPEX_BANNER_COUNT;
}
